package cn.acg138.rover;
public class TestAttributes {
 static int checks=0; static void expect(String text,String action,String cat,String color,String size,String pos){VoiceCommands.Intent i=VoiceCommands.parse(text);if(i==null||!i.action.equals(action)||!i.category.equals(cat)||!i.color.equals(color)||!i.size.equals(size)||!i.position.equals(pos))throw new AssertionError(text+" -> "+(i==null?"null":i.action+"/"+i.category+"/"+i.color+"/"+i.size+"/"+i.position));checks++;System.out.println(text+"|"+i.action+"|"+i.category+"|"+i.color+"|"+i.size+"|"+i.position);}
 public static void main(String[]args){expect("找到红色水瓶","go","bottle","red","","");expect("找到红色大箱子","go","box","red","large","");expect("找到大的红色箱子","go","box","red","large","");expect("小车找到左边的小蓝色箱子","go","box","blue","small","left");expect("只识别红色水瓶","find","bottle","red","","");expect("只查找小箱子","find","box","","small","");expect("红色箱子在哪里","find","box","red","","");expect("跟随黑色水瓶","follow","bottle","black","","");expect("前往中间绿色的箱子","go","box","green","","center");expect("找到粉红色箱子","go","box","pink","","");expect("找到杯子","go","cup","","","");expect("找到小猫","go","cat","","","");expect("跟随我","follow","person","","","");expect("停车","stop","","","","");if(VoiceCommands.parse("不要找红色水瓶")!=null)throw new AssertionError("negation");if(VoiceCommands.parse("找红色蓝色箱子")!=null)throw new AssertionError("ambiguous color");if(VoiceCommands.parse("找大大小箱子")!=null)throw new AssertionError("ambiguous size");System.out.println("PASS Java semantic attributes "+(checks+3));}
}
